const records = [
['ИИ','Искусственный интеллект','искусственный интеллект ии ai интеллектуальная система','Искусственный интеллект — область информатики, создающая системы для задач, обычно требующих интеллектуальных способностей: распознавания образов, планирования, понимания языка и принятия решений. Это широкий термин: он включает и простые классификаторы, и большие языковые модели.','https://ru.wikipedia.org/wiki/Искусственный_интеллект'],
['ИИ','Что такое машинное обучение','машинное обучение ml machine learning обучается данные','Машинное обучение — методы, при которых система настраивает параметры по примерам данных, а не только исполняет вручную заданный набор правил. Качество зависит от данных, постановки задачи, проверки на отложенных примерах и анализа ошибок.','https://ru.wikipedia.org/wiki/Машинное_обучение'],
['ИИ','Что такое нейронная сеть','нейросеть нейронная сеть нейроны веса слои','Искусственная нейронная сеть — модель из связанных вычислительных узлов. Данные проходят через слои, веса преобразуют входы, а обучение настраивает эти веса по функции потерь. Само наличие нейросети не означает, что она умеет отвечать на любые вопросы.','https://ru.wikipedia.org/wiki/Искусственная_нейронная_сеть'],
['ИИ','Что такое LLM','llm большая языковая модель large language model текст генерация','Большая языковая модель обучается на больших наборах текста и обычно предсказывает следующие токены, что позволяет генерировать связные продолжения. Она может ошибаться или придумывать детали, поэтому важные факты нужно проверять по источникам.','https://en.wikipedia.org/wiki/Large_language_model'],
['ИИ','Классификатор и генеративная модель','классификатор генеративная модель отличие классы генерация текста','Классификатор выбирает метку из ограниченного набора категорий, например «погода» или «программирование». Генеративная модель создаёт последовательность токенов и формулирует новые ответы. Базовая LEDERG NEIRO — небольшой классификатор с шаблонами, а не LLM.','https://en.wikipedia.org/wiki/Statistical_classification'],
['ИИ','Обучение с учителем','обучение с учителем supervised learning метки','При обучении с учителем модель получает примеры, где известен правильный ответ или метка. Она сравнивает предсказание с меткой и обновляет параметры, уменьшая функцию потерь. Для честной оценки нужна отдельная тестовая выборка.','https://en.wikipedia.org/wiki/Supervised_learning'],
['ИИ','Что такое переобучение модели','переобучение overfitting модель обучение данные','Переобучение возникает, когда модель слишком хорошо запоминает обучающие примеры, но хуже работает на новых. Помогают разнообразные данные, регуляризация, ранняя остановка и независимая тестовая выборка.','https://en.wikipedia.org/wiki/Overfitting'],
['ИИ','Что такое токен','токен токенизация текст кусок слова модель','Токен — единица, на которую модель разбивает текст: слово, часть слова, символ или иной фрагмент. Токенизация влияет на длину контекста и вычисления. Токен не обязательно совпадает с целым словом.','https://en.wikipedia.org/wiki/Lexical_analysis'],
['ИИ','Что такое функция потерь','функция потерь loss ошибка обучение градиент','Функция потерь численно оценивает, насколько предсказание модели отличается от ожидаемого результата. Алгоритм обучения использует её градиент, чтобы менять параметры в сторону уменьшения ошибки. Выбор функции зависит от задачи.','https://en.wikipedia.org/wiki/Loss_function'],
['ИИ','Градиентный спуск','градиентный спуск gradient descent шаг learning rate','Градиентный спуск — способ оптимизации: параметры постепенно меняются против направления градиента функции потерь. Размер шага задаёт learning rate. Слишком большой шаг может мешать сходимости, а слишком маленький замедляет обучение.','https://en.wikipedia.org/wiki/Gradient_descent'],
['ИИ','Backpropagation','обратное распространение ошибки backpropagation градиенты веса','Обратное распространение ошибки вычисляет производные функции потерь по параметрам сети с помощью цепного правила. Затем оптимизатор обновляет веса. Backpropagation вычисляет градиенты, а способ обновления задаётся оптимизатором.','https://en.wikipedia.org/wiki/Backpropagation'],
['ИИ','Что такое эмбеддинг','эмбеддинг embedding вектор смысл представление','Эмбеддинг — векторное представление объекта, например слова или документа. Векторное пространство может кодировать статистические связи и смысловую близость; сравнение векторов используют для семантического поиска.','https://en.wikipedia.org/wiki/Word_embedding'],
['ИИ','Что такое RAG','rag retrieval augmented generation поиск извлечение знаний контекст','RAG — подход, в котором система сначала ищет релевантные документы, а затем передаёт их содержание языковой модели для подготовки ответа. Качество зависит от поиска, документов и корректного цитирования.','https://en.wikipedia.org/wiki/Retrieval-augmented_generation'],
['ИИ','Галлюцинации искусственного интеллекта','галлюцинация ии выдумывает факт неверный ответ','Галлюцинация ИИ — правдоподобный, но неверный или неподтверждённый ответ. Риск снижают поиск по надёжным источникам, цитирование, признание неопределённости и проверка фактов. Уверенный тон не доказывает истинность.','https://en.wikipedia.org/wiki/Hallucination_(artificial_intelligence)'],
['ИИ','Мультимодальные модели','мультимодальная модель текст изображение звук видео','Мультимодальная модель работает с несколькими типами данных: текстом, изображениями, звуком или видео. Возможности зависят от архитектуры и обучения; обычный текстовый классификатор без специального кода изображения не понимает.','https://en.wikipedia.org/wiki/Multimodal_learning'],
['ИИ','MLP и функция tanh','mlp полносвязная сеть tanh скрытый слой нейрон','MLP — многослойный перцептрон со слоями обучаемых весов. tanh — активация, переводящая значения в диапазон от −1 до 1. LEDERG NEIRO использует этот элемент в учебной сети для классификации намерений.','https://en.wikipedia.org/wiki/Multilayer_perceptron'],
['Программирование','Что такое JavaScript','javascript js язык браузер код frontend','JavaScript — язык программирования, работающий в браузерах и средах вроде Node.js. В браузере он изменяет интерфейс, обрабатывает события, выполняет вычисления и запрашивает веб-API. Секретные ключи нельзя хранить в общедоступном клиентском коде.','https://developer.mozilla.org/ru/docs/Web/JavaScript'],
['Программирование','Что такое HTML','html разметка страница элементы структура сайт','HTML описывает структуру веб-страницы: заголовки, абзацы, ссылки, формы и другие элементы. Оформление задаёт CSS, а интерактивную логику обычно обеспечивает JavaScript.','https://developer.mozilla.org/ru/docs/Web/HTML'],
['Программирование','Что такое CSS','css стили оформление адаптивный интерфейс сайт','CSS задаёт оформление HTML: цвета, размеры, расположение, анимации и адаптивность. Для отзывчивых интерфейсов применяют Flexbox, Grid, относительные единицы и media queries.','https://developer.mozilla.org/ru/docs/Web/CSS'],
['Программирование','Что такое API','api интерфейс программирования запрос ответ сервис','API — согласованный способ взаимодействия программ. Веб-API часто использует HTTP-запросы и JSON-ответы. API может требовать ключ или авторизацию; секретные ключи нельзя помещать в публичный фронтенд-код.','https://developer.mozilla.org/ru/docs/Glossary/API'],
['Программирование','HTTP и HTTPS','http https протокол запрос ответ tls шифрование','HTTP — протокол передачи данных веба. HTTPS — HTTP поверх TLS, что помогает обеспечить конфиденциальность и целостность передачи и проверить сертификат сервера. HTTPS не гарантирует честность содержимого сайта.','https://developer.mozilla.org/ru/docs/Glossary/HTTPS'],
['Программирование','Что такое JSON','json данные объект массив сериализация','JSON — текстовый формат обмена данными, поддерживающий объекты, массивы, строки, числа, логические значения и null. В JavaScript JSON.parse разбирает JSON-строку, JSON.stringify сериализует данные. Входящие данные нужно валидировать.','https://developer.mozilla.org/ru/docs/Web/JavaScript/Reference/Global_Objects/JSON'],
['Программирование','Что такое DOM','dom document object model html дерево события','DOM — объектное представление документа, с которым взаимодействует JavaScript. Через DOM код меняет элементы и текст и подписывается на события. Для обычного пользовательского текста безопаснее использовать textContent, а не вставлять сырой HTML.','https://developer.mozilla.org/ru/docs/Web/API/Document_Object_Model'],
['Программирование','Асинхронность JavaScript','async await promise асинхронный javascript ожидание запрос','Асинхронность позволяет ждать операции ввода-вывода, не блокируя основной поток на всё время ожидания. Promise описывает будущий результат, async объявляет асинхронную функцию, await ждёт Promise. Ошибки обрабатывают через try/catch.','https://developer.mozilla.org/ru/docs/Web/JavaScript/Reference/Statements/async_function'],
['Программирование','Что такое fetch','fetch запрос javascript http api','fetch — браузерный API для HTTP-запросов. Он возвращает Promise с Response; до обработки тела проверь response.ok, затем вызови json() или text(). Запрос к другому домену зависит от настроек CORS сервера.','https://developer.mozilla.org/ru/docs/Web/API/Fetch_API'],
['Программирование','Что такое CORS','cors браузер другой домен запрос политика','CORS — механизм браузера, позволяющий серверу явно разрешать странице читать ответы с другого origin. Если сервер не выставляет нужные заголовки, фронтенд не может обойти ограничение сам. Используй API с поддержкой CORS или свой backend.','https://developer.mozilla.org/ru/docs/Web/HTTP/CORS'],
['Программирование','Что такое localStorage','localstorage локальное хранилище браузер сохранить данные','localStorage хранит строки в браузере отдельно для каждого origin и сохраняет их между посещениями. Оно подходит для настроек и небольших локальных данных, но не синхронизируется между устройствами и может быть очищено. Не храни там пароли и секреты.','https://developer.mozilla.org/ru/docs/Web/API/Window/localStorage'],
['Программирование','Что такое WebGPU','webgpu gpu графический процессор браузер вычисления','WebGPU — веб-API для доступа к графическим и вычислительным возможностям совместимого GPU. Поддержка зависит от браузера, ОС и устройства; нужны проверки доступности и запасной сценарий. Он может ускорять локальные модели, но не предоставляет серверных вычислений на Pages.','https://developer.mozilla.org/en-US/docs/Web/API/WebGPU_API'],
['Программирование','Что такое Python','python язык программирования синтаксис автоматизация','Python — высокоуровневый язык с читаемым синтаксисом, используемый для автоматизации, веб-сервисов, анализа данных и машинного обучения. Для запуска нужен интерпретатор; GitHub Pages сам по себе Python-код не исполняет.','https://docs.python.org/ru/3/'],
['Программирование','Что такое алгоритм','алгоритм последовательность шагов задача решение','Алгоритм — конечная последовательность однозначных действий для решения задачи. Полезно определить входы, выходы, граничные случаи и сложность по времени и памяти.','https://ru.wikipedia.org/wiki/Алгоритм'],
['Программирование','Что такое рекурсия','рекурсия функция вызывает саму себя базовый случай','Рекурсия — когда функция прямо или косвенно вызывает саму себя. Для завершения нужен базовый случай; иначе возможны бесконечные вызовы и переполнение стека. Для простых повторений цикл зачастую проще.','https://developer.mozilla.org/en-US/docs/Glossary/Recursion'],
['Программирование','Что такое Git','git система контроля версий коммит ветка история','Git — распределённая система контроля версий. Коммит фиксирует изменения, ветки позволяют работать параллельно, а merge или rebase помогают объединять изменения. Перед правкой проверяй состояние и историю репозитория.','https://git-scm.com/book/ru/v2'],
['GitHub','Что такое GitHub','github репозиторий код pull request issue','GitHub — платформа для Git-репозиториев и совместной разработки, с задачами, pull request, проверками CI и управлением доступом. Публичный репозиторий доступен всем: не помещай туда токены, пароли и личные данные.','https://docs.github.com/ru/get-started'],
['GitHub','Что такое GitHub Pages','github pages статический хостинг сайт html css js','GitHub Pages публикует статические HTML, CSS, JavaScript и другие файлы из репозитория. Он не запускает постоянный сервер Python/Node и не подходит для хранения секретов. Динамика должна работать в браузере или обращаться к внешнему API с поддержкой CORS.','https://docs.github.com/ru/pages'],
['GitHub','Что такое GitHub Actions','github actions workflow автоматизация тесты deploy ci cd','GitHub Actions запускает workflow по событиям, например push или pull request. В LEDERG NEIRO workflow запускает npm test и при успехе публикует сайт через Pages. Ошибки нужно смотреть в Actions и логах конкретного шага.','https://docs.github.com/ru/actions'],
['GitHub','Что такое pull request','pull request pr запрос на слияние ревью github','Pull request предлагает изменить одну ветку на основе другой. Он позволяет изучить diff, обсудить код и потребовать успешные тесты до слияния. Для крупных изменений полезна отдельная ветка.','https://docs.github.com/ru/pull-requests'],
['GitHub','Что такое README','readme документация репозиторий запуск проекта','README — главная документация проекта: назначение, запуск, тестирование, ограничения и важные файлы. Документ должен отражать реальное поведение кода, а не обещать несуществующие функции.','https://docs.github.com/ru/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-readmes'],
['Безопасность','Как хранить API-ключи','api ключ секрет env секреты github secrets фронтенд','Не вшивай секретный API-ключ в HTML или JavaScript: клиентский код может прочитать каждый посетитель. Держи секрет на backend или в защищённом хранилище секретов CI. Backend должен проверять запросы и ограничивать расход.','https://docs.github.com/ru/actions/security-guides/using-secrets-in-github-actions'],
['Безопасность','Что такое фишинг','фишинг мошенничество ссылка пароль поддельный сайт','Фишинг пытается выманить пароль, код подтверждения или платёжные данные через поддельные сообщения и сайты. Проверяй домен, не открывай неожиданные вложения, не сообщай одноразовые коды и включай MFA.','https://www.cisa.gov/secure-our-world/recognize-and-report-phishing'],
['Безопасность','Как создать надёжный пароль','пароль надежный пароль менеджер паролей уникальный','Используй длинный уникальный пароль для каждого сервиса, лучше сгенерированный менеджером паролей. Включи MFA или passkey, если доступны. Не повторяй пароль и не пересылай коды входа другим людям.','https://www.cisa.gov/secure-our-world/use-strong-passwords'],
['Безопасность','Что такое MFA','mfa 2fa двухфакторная аутентификация безопасность вход','MFA требует более одного фактора подтверждения личности, например пароль и аппаратный ключ, приложение-аутентификатор или passkey. Это снижает риск захвата аккаунта при утечке одного пароля.','https://www.cisa.gov/secure-our-world/turn-mfa'],
['Безопасность','Что такое XSS','xss cross site scripting внедрение скрипта безопасность','XSS возникает, когда атакующий добивается выполнения своего скрипта в контексте сайта. Используй textContent для текста, избегай небезопасного innerHTML с пользовательским вводом, валидируй данные и настрой CSP.','https://developer.mozilla.org/en-US/docs/Web/Security/Types_of_attacks#cross-site_scripting_xss'],
['Безопасность','Что такое SQL-инъекция','sql injection запрос база данных параметры безопасность','SQL-инъекция возникает, если пользовательский ввод влияет на структуру SQL-запроса. Используй параметризованные запросы или подготовленные выражения, ограничивай права базы и не создавай запрос конкатенацией строк.','https://owasp.org/www-community/attacks/SQL_Injection'],
['Безопасность','Что такое шифрование','шифрование encryption криптография ключ расшифровка','Шифрование преобразует читаемые данные в форму, восстанавливаемую при наличии ключа. Симметричные алгоритмы используют общий секрет, асимметричные — открытую и закрытую пару ключей. Управление ключами столь же важно, как алгоритм.','https://ru.wikipedia.org/wiki/Шифрование'],
['Безопасность','Как безопасно загружать файлы','загрузка файла upload проверка тип размер безопасность','Приём файлов должен ограничивать размер и разрешённые типы, проверять содержимое, генерировать безопасные имена и хранить файлы вне исполняемого каталога. Не доверяй расширению и Content-Type, присланным клиентом.','https://cheatsheetseries.owasp.org/cheatsheets/File_Upload_Cheat_Sheet.html'],
['Сети','Что такое IP-адрес','ip адрес ipv4 ipv6 сеть устройство маршрутизация','IP-адрес идентифицирует сетевой интерфейс для доставки пакетов. IPv4 использует 32 бита, IPv6 — 128. Частные адреса применяют в локальных сетях; для доступа из интернета дополнительно важны маршрутизация, NAT и правила фильтрации.','https://ru.wikipedia.org/wiki/IP-адрес'],
['Сети','Что такое DNS','dns доменное имя ip сервер система имен','DNS сопоставляет доменные имена с записями, в том числе IP-адресами. Резолверы кэшируют ответы на время TTL. Изменения DNS могут проявляться с задержкой из-за кэширования.','https://www.cloudflare.com/learning/dns/what-is-dns/'],
['Сети','Что такое VPN','vpn виртуальная частная сеть шифрование туннель','VPN создаёт сетевой туннель между устройством и VPN-сервером или корпоративной сетью. Он может защищать трафик от локальной сети, но не делает пользователя автоматически анонимным и не гарантирует безопасность сайтов.','https://www.cloudflare.com/learning/access-management/what-is-a-vpn/'],
['Сети','TCP и UDP','tcp udp протокол соединение пакеты задержка','TCP обеспечивает доставку и порядок байтового потока. UDP передаёт датаграммы без встроенной гарантии доставки и порядка. UDP подходит приложениям с низкими задержками, но надёжность при необходимости реализует само приложение.','https://www.cloudflare.com/learning/ddos/glossary/user-datagram-protocol-udp/'],
['Компьютеры','Что такое CPU','cpu процессор центральный процессор ядра инструкции','CPU — центральный процессор, исполняющий инструкции программ. Производительность зависит от архитектуры, эффективности ядер, частоты, кеша, памяти, охлаждения и типа нагрузки; одной частоты недостаточно для сравнения.','https://ru.wikipedia.org/wiki/Центральный_процессор'],
['Компьютеры','Что такое GPU','gpu видеокарта графический процессор параллельные вычисления','GPU рассчитан на параллельную обработку множества операций. Помимо графики он ускоряет некоторые научные и ИИ-вычисления. Прирост зависит от модели, объёма памяти, драйвера и программного обеспечения.','https://ru.wikipedia.org/wiki/Графический_процессор'],
['Компьютеры','Что такое RAM','ram оперативная память озу память компьютера','RAM хранит код и данные работающих программ. Обычно это энергозависимая память, содержимое которой теряется после отключения питания. Недостаток RAM может вызывать активное использование файла подкачки и снижать отзывчивость.','https://ru.wikipedia.org/wiki/Оперативная_память'],
['Компьютеры','SSD и HDD','ssd hdd диск накопитель память скорость','HDD хранит данные на вращающихся магнитных пластинах; SSD использует флеш-память без движущихся частей. SSD обычно быстрее при случайном чтении. Резервные копии нужны для обоих типов накопителей.','https://ru.wikipedia.org/wiki/Твердотельный_накопитель'],
['Компьютеры','Что такое операционная система','операционная система ос windows linux macos процессы файлы','Операционная система управляет процессами, памятью, файлами, устройствами и правами доступа, предоставляя приложениям системные интерфейсы. Примеры — Windows, Linux, macOS, Android и iOS.','https://ru.wikipedia.org/wiki/Операционная_система'],
['Компьютеры','Что такое Linux','linux ядро дистрибутив терминал открытая система','Linux — семейство систем на ядре Linux. Ubuntu, Debian и Fedora — примеры дистрибутивов. Команды и расположения файлов могут отличаться в зависимости от системы и оболочки.','https://www.kernel.org/'],
['Наука','Что такое атом','атом ядро протон нейтрон электрон вещество','Атом состоит из ядра с протонами и, кроме обычного водорода-1, нейтронами, окружённого электронами. Химические свойства во многом определяются электронной структурой.','https://ru.wikipedia.org/wiki/Атом'],
['Наука','Что такое ДНК','днк dna ген генетическая информация наследственность','ДНК — молекула, последовательность нуклеотидов которой хранит наследственную информацию многих организмов. Часть участков участвует в кодировании РНК и белков, другие регулируют клеточные процессы. Не вся ДНК кодирует белки.','https://ru.wikipedia.org/wiki/Дезоксирибонуклеиновая_кислота'],
['Наука','Что такое эволюция','эволюция естественный отбор популяция виды биология','Эволюция — изменение наследуемых характеристик популяций на протяжении поколений. Механизмы включают естественный отбор, мутации, генетический дрейф и поток генов.','https://ru.wikipedia.org/wiki/Эволюция'],
['Наука','Что такое фотосинтез','фотосинтез растения свет углекислый газ кислород','Фотосинтез использует энергию света для синтеза органических веществ. При кислородном фотосинтезе вода служит источником электронов и выделяется кислород. На скорость влияют свет, вода, углекислый газ и условия среды.','https://ru.wikipedia.org/wiki/Фотосинтез'],
['Наука','Что такое гравитация','гравитация сила тяжести масса пространство время','Гравитация — взаимодействие, связанное с массой и энергией. В механике Ньютона она описывается силой притяжения, в общей теории относительности — кривизной пространства-времени. Для бытовых расчётов часто достаточно приближения Ньютона.','https://ru.wikipedia.org/wiki/Гравитация'],
['Наука','Скорость света','скорость света вакуум 299792458 метр секунда','Скорость света в вакууме — точная константа 299 792 458 метров в секунду. В среде свет распространяется иначе в зависимости от её свойств. Эта величина важна для электромагнетизма и специальной теории относительности.','https://ru.wikipedia.org/wiki/Скорость_света'],
['Наука','Что такое электрический ток','электрический ток заряд электроны амперы напряжение','Электрический ток — упорядоченное движение зарядов. Сила тока измеряется в амперах, напряжение — в вольтах, сопротивление — в омах. Для простого омического участка закон Ома: I = U / R.','https://ru.wikipedia.org/wiki/Электрический_ток'],
['Наука','Что такое чёрная дыра','черная дыра горизонт событий гравитация космос','Чёрная дыра — область пространства-времени с горизонтом событий, изнутри которого свет не может уйти к далёкому наблюдателю. Её изучают по влиянию на окружающее вещество, орбиты звёзд и гравитационные волны.','https://ru.wikipedia.org/wiki/Чёрная_дыра'],
['Космос','Солнечная система','солнечная система солнце планеты земля орбита','Солнечная система включает Солнце и объекты, связанные с ним гравитацией: восемь планет, спутники, карликовые планеты, астероиды и кометы. Порядок планет: Меркурий, Венера, Земля, Марс, Юпитер, Сатурн, Уран, Нептун.','https://solarsystem.nasa.gov/'],
['Космос','Почему бывает день и ночь','день ночь вращение земли сутки солнце','День и ночь сменяются из-за вращения Земли вокруг оси примерно за сутки. Полушарие, обращённое к Солнцу, освещено; противоположная сторона находится в ночи.','https://ru.wikipedia.org/wiki/Смена_дня_и_ночи'],
['Космос','Почему бывают времена года','времена года наклон оси земли лето зима орбита','Времена года связаны главным образом с наклоном земной оси примерно на 23,4° относительно плоскости орбиты. Из-за этого меняются высота Солнца и продолжительность дня. Причина не просто в расстоянии до Солнца.','https://science.nasa.gov/earth/'],
['Математика','Что такое процент','процент проценты от числа расчет доля','Один процент равен одной сотой: 1% = 0,01. Чтобы найти p процентов от x, вычисли x × p / 100. Процентное изменение от B к A: (A − B) / B × 100%, если B не равно нулю.','https://ru.wikipedia.org/wiki/Процент'],
['Математика','Число Пи','число пи pi 3.14159 окружность диаметр','π — отношение длины окружности к диаметру в евклидовой геометрии. Это иррациональное число приблизительно 3,1415926535. Площадь круга равна πr², длина окружности — 2πr.','https://ru.wikipedia.org/wiki/Пи_(число)'],
['Математика','Что такое вероятность','вероятность событие шанс от нуля до единицы','Вероятность описывает меру возможности события и лежит от 0 до 1. Для равновозможных исходов она равна числу благоприятных исходов, делённому на число всех исходов. Данные могут расходиться с теоретической моделью.','https://ru.wikipedia.org/wiki/Теория_вероятностей'],
['Математика','Среднее арифметическое','среднее арифметическое сумма чисел разделить','Среднее арифметическое — сумма всех значений, разделённая на их количество. Оно чувствительно к крайним значениям; иногда медиана лучше показывает центр распределения.','https://ru.wikipedia.org/wiki/Среднее_арифметическое'],
['Математика','Двоичная система счисления','двоичная система бинарная 0 1 биты компьютер','Двоичная система использует цифры 0 и 1, а разряды имеют вес степени двойки. Например, 1011₂ = 1×8 + 0×4 + 1×2 + 1 = 11₁₀. Данные компьютера на низком уровне кодируются битами.','https://ru.wikipedia.org/wiki/Двоичная_система_счисления'],
['География','Что такое экватор','экватор земля широта ноль градус','Экватор — воображаемая линия вокруг Земли, равноудалённая от полюсов. Он соответствует широте 0° и делит планету на Северное и Южное полушария.','https://ru.wikipedia.org/wiki/Экватор'],
['География','Что такое часовой пояс','часовой пояс время utc смещение земля','Часовые пояса — области с согласованным гражданским временем. Смещения отсчитываются от UTC, но политические правила и сезонный перевод часов зависят от страны. В программах используй идентификаторы IANA, например Europe/Moscow, а не фиксированный сдвиг для всех дат.','https://en.wikipedia.org/wiki/Time_zone'],
['География','Климат и погода','климат погода отличие прогноз атмосферные условия','Погода описывает текущее и краткосрочное состояние атмосферы, а климат — статистические характеристики погоды за длительный период. Один холодный день не опровергает многолетний тренд климата.','https://ru.wikipedia.org/wiki/Климат'],
['География','Что такое океан','океан мировой океан тихий атлантический индийский','Мировой океан — взаимосвязанная водная оболочка Земли. Обычно выделяют Тихий, Атлантический, Индийский, Южный и Северный Ледовитый океаны. Океаны влияют на климат, экосистемы и круговорот углерода.','https://oceanservice.noaa.gov/facts/ocean.html'],
['История','Промышленная революция','промышленная революция индустриализация фабрики паровая машина','Промышленная революция — переход от преимущественно аграрного и ремесленного производства к машинному фабричному. Она началась в Великобритании в XVIII веке и изменила транспорт, труд, города и общество.','https://en.wikipedia.org/wiki/Industrial_Revolution'],
['История','Что такое письменность','письменность символы запись язык история','Письменность — система знаков для записи языка или сообщений. Системы могут быть алфавитными, слоговыми, морфемными и смешанными. Письменность позволяет сохранять и передавать сведения за пределами устной памяти.','https://ru.wikipedia.org/wiki/Письменность'],
['Общество','Что такое демократия','демократия выборы власть граждан представительство','Демократия — политическая система, где власть легитимируется участием граждан прямо или через представителей. Системы различаются институтами, конституционными ограничениями, защитой прав и практикой выборов.','https://ru.wikipedia.org/wiki/Демократия'],
['Продуктивность','Как лучше учиться','учиться обучение память повторение интервальное обучение','Для усвоения полезны активное воспроизведение без подсказки, интервальные повторения и практика на задачах. Короткие регулярные занятия часто эффективнее одного длинного подхода; перерывы и сон помогают закреплению памяти.','https://en.wikipedia.org/wiki/Spaced_repetition'],
['Продуктивность','Как решать сложную задачу','решить задача план разбить шаги проверить результат','Разбей задачу на проверяемые подзадачи, опиши ожидаемый результат, найди ограничения и выполни самый рискованный тест пораньше. После каждого шага проверяй результат, а не просто продолжай работу.','https://en.wikipedia.org/wiki/Problem_solving'],
['Язык','Что такое метафора','метафора язык образное выражение перенос значение','Метафора переносит название или свойство с одного объекта на другой по сходству или ассоциации, например «время летит». Она помогает выражать абстрактные понятия через знакомые образы.','https://ru.wikipedia.org/wiki/Метафора'],
['Язык','Факт и мнение','факт мнение доказательство интерпретация утверждение','Факт — утверждение, истинность которого можно проверять наблюдениями или свидетельствами. Мнение выражает оценку или позицию. Важно отделять измеренные данные от интерпретации и указывать источники и неопределённость.','https://en.wikipedia.org/wiki/Fact'],
['Здоровье','Что такое сон','сон отдых режим циркадный ритм здоровье','Сон — биологическое состояние, важное для внимания, памяти и обмена веществ. Потребность индивидуальна и зависит от возраста. Регулярный режим и достаточная продолжительность помогают поддерживать здоровье; медицинские проблемы стоит обсуждать со специалистом.','https://www.cdc.gov/sleep/about/index.html'],
['Экология','Переработка отходов','переработка отходов recycle сортировка материалы экология','Переработка возвращает пригодные материалы в производственный цикл, уменьшая потребность в первичном сырье. Возможность переработки зависит от материала, местной инфраструктуры и загрязнения. Сокращение потребления и повторное использование часто предпочтительнее.','https://www.epa.gov/recycle'],
['LEDERG','Как работает LEDERG NEIRO','lederg neiro своя модель локальная система архитектура','Система состоит из обучаемого MLP-классификатора, выбирающего тему запроса; базы знаний со справочными карточками; и инструментов для времени, арифметики, конвертации, погоды и поиска по открытым источникам. Это ранняя система, не эквивалент ChatGPT.','https://github.com/LEDERG777-TEXNARIC/LEDERG_NEIRO'],
['LEDERG','Где хранится история LEDERG NEIRO','история диалогов хранение localstorage privacy lederg','История чатов и личные примеры LEDERG NEIRO сохраняются в localStorage текущего браузера. Они не синхронизируются между устройствами и могут исчезнуть при очистке данных сайта. Для поиска или погоды соответствующий запрос отправляется внешнему публичному сервису.','https://developer.mozilla.org/ru/docs/Web/API/Window/localStorage'],
['LEDERG','Как добавить знания LEDERG NEIRO','добавить знания база знаний карточки knowledge обучение','Новые справочные знания добавляются в knowledge.js в виде карточки: категория, заголовок, ключевые слова, ответ и ссылка на источник. Это расширяет базу ответов, но не обучает веса классификатора и не превращает его в генеративную LLM.','https://github.com/LEDERG777-TEXNARIC/LEDERG_NEIRO'],
['LEDERG','Как обучить LEDERG NEIRO на своих фразах','обучение примеры фразы намерения лаборатория пользовательские примеры','В разделе «Обучение модели» добавь характерную фразу и выбери правильную категорию. После переобучения классификатор использует пример для распознавания класса. Не добавляй пароли, секретные ключи, личные данные или чужие приватные сообщения.','https://github.com/LEDERG777-TEXNARIC/LEDERG_NEIRO'],
['LEDERG','Что умеет LEDERG NEIRO','возможности функции нейро поиск время москва погода калькулятор','Доступны справочные карточки, время по Москве, безопасный калькулятор, конвертация единиц, текущая погода через Open-Meteo, поиск Wikipedia с ссылками и прямые ссылки на общий веб-поиск. Система пока не генерирует свободный текст как большая языковая модель.','https://github.com/LEDERG777-TEXNARIC/LEDERG_NEIRO']
];
records.push(
['ИИ','Что такое трансформер','transformer трансформер attention self attention архитектура llm','Трансформер — архитектура нейросети, использующая механизм внимания для обработки последовательностей. Он стал основой многих языковых моделей. Сам по себе трансформер не гарантирует высокий интеллект: важны данные, масштаб, обучение и оценка качества.','https://arxiv.org/abs/1706.03762'],
['ИИ','Что такое внимание в нейросетях','attention механизм внимания query key value контекст','Механизм внимания помогает модели вычислять, какие части входной последовательности важны для каждого шага. В трансформере запросы, ключи и значения комбинируются в контекстные представления.','https://arxiv.org/abs/1706.03762'],
['ИИ','Что такое контекстное окно','контекстное окно context window токены длина сообщения llm','Контекстное окно — максимальный объём токенов, который модель учитывает в одном запросе. Длинный контекст требует больше памяти и вычислений; важные детали могут теряться из-за ограничений архитектуры и внимания.','https://platform.openai.com/docs/guides/text-generation'],
['ИИ','Что такое fine-tuning','fine tuning дообучение модель веса адаптация данные','Fine-tuning — дополнительное обучение предварительно обученной модели на специализированных примерах. Оно может изменить стиль или улучшить узкую задачу, но требует качественных данных, оценки регрессий и соблюдения лицензии исходной модели.','https://huggingface.co/docs/transformers/training'],
['ИИ','Что такое квантизация модели','квантизация quantization модель веса память int8 int4','Квантизация хранит веса или вычисления в менее точном числовом формате, например 8 или 4 бита. Это сокращает память и иногда ускоряет вывод, но может снизить качество; эффект зависит от модели и метода.','https://huggingface.co/docs/optimum/concept_guides/quantization'],
['ИИ','Что такое открытая модель','open weights открытые веса лицензия модель скачать','Открытые веса позволяют получить параметры модели и запускать её самостоятельно, если лицензия это разрешает. Открытые веса не всегда означают открытый набор обучения, полный исходный код или неограниченное коммерческое использование.','https://huggingface.co/docs/hub/models'],
['ИИ','Что такое оценка языковой модели','llm evaluation benchmark тестирование метрики точность','Оценка языковой модели использует тестовые наборы, экспертную проверку, автоматические метрики и анализ ошибок. Один benchmark не описывает все способности; тесты нужно подбирать под реальные задачи и проверять риск утечки данных из обучения.','https://huggingface.co/docs/evaluate/index'],
['ИИ','Как написать хороший запрос нейросети','prompt запрос ии контекст цель формат ограничение','Хороший запрос описывает цель, контекст, ограничения и желаемый формат результата. Для сложной задачи дай пример ожидаемого ответа и попроси явно отметить неопределённость. Результат всё равно нужно проверять, особенно факты и расчёты.','https://platform.openai.com/docs/guides/prompt-engineering'],
['ИИ','Что такое векторная база данных','векторная база данных embeddings similarity search семантический поиск','Векторная база хранит векторные представления объектов и помогает искать ближайшие по выбранной метрике. Её часто используют для семантического поиска и RAG. Качество зависит от эмбеддингов, разбиения документов и фильтрации.','https://en.wikipedia.org/wiki/Vector_database'],
['ИИ','Что такое нейросетевой агент','агент ai tool use инструменты цель планирование','ИИ-агент — система, которая использует модель для выбора действий и взаимодействует с инструментами или средой. Без ограничений агент может ошибаться, поэтому нужны контроль доступа, лимиты, журналирование и подтверждение важных действий.','https://en.wikipedia.org/wiki/Intelligent_agent'],
['Программирование','Что такое TypeScript','typescript ts типы javascript компиляция','TypeScript добавляет статическую систему типов к JavaScript и компилируется в JavaScript. Типы помогают находить ошибки до запуска, но удаляются при компиляции и не заменяют проверку входящих данных во время работы.','https://www.typescriptlang.org/docs/'],
['Программирование','Что такое Node.js','node js сервер javascript npm runtime','Node.js — среда выполнения JavaScript вне браузера, часто используемая для серверов и утилит. Она предоставляет API для файловой системы, сети и процессов. Возможности браузера и Node.js различаются: например, document доступен в браузере, но не в обычном Node.js.','https://nodejs.org/en/learn'],
['Программирование','Что такое npm','npm пакет менеджер package json зависимости javascript','npm — менеджер пакетов и инструмент экосистемы Node.js. package.json описывает проект и команды, а зависимости устанавливаются отдельно. Версии и lock-файл помогают делать сборки воспроизводимыми; проверяй источник пакетов и лицензии.','https://docs.npmjs.com/about-npm'],
['Программирование','Что такое регулярное выражение','regex regexp регулярное выражение поиск строки шаблон','Регулярное выражение описывает шаблон текста для поиска, проверки или замены. Оно подходит для простых форматов, но плохо заменяет полноценный парсер вложенных языков. Ограничивай вход, чтобы избежать чрезмерно дорогих шаблонов.','https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Regular_expressions'],
['Программирование','Что такое обработка ошибок','try catch exception ошибка исключение программа','Обработка ошибок позволяет программе корректно реагировать на сбои. Проверяй ошибки сети, формат данных и граничные случаи, показывай понятное сообщение и сохраняй техническую диагностику без секретов. Не скрывай ошибку пустым catch.','https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/try...catch'],
['Программирование','Что такое тестирование ПО','unit test integration e2e тесты программное обеспечение','Юнит-тест проверяет маленькую единицу логики; интеграционный тест — взаимодействие частей; end-to-end тест — пользовательский сценарий. Тест должен фиксировать наблюдаемое поведение и надёжно ловить регрессии.','https://en.wikipedia.org/wiki/Software_testing'],
['Программирование','Что такое CI/CD','ci cd непрерывная интеграция доставка автоматическая публикация','CI автоматически проверяет изменения, например тестами и сборкой. CD автоматизирует подготовку или публикацию релизов. Хороший pipeline останавливает деплой при ошибке проверок и сохраняет логи для диагностики.','https://docs.github.com/en/actions'],
['Программирование','Что такое алгоритмическая сложность','сложность алгоритма big o время память big-o','Big O описывает, как растут затраты алгоритма при увеличении входа. O(n) означает линейный рост, O(n²) — квадратичный. Реальная скорость также зависит от констант, памяти, ввода-вывода и конкретных данных.','https://en.wikipedia.org/wiki/Big_O_notation'],
['Программирование','Что такое структура данных','структуры данных массив список стек очередь хеш таблица','Структуры данных организуют информацию для разных операций. Массив удобен для индексированного доступа, стек работает по принципу последним пришёл — первым вышел, очередь — первым пришёл — первым вышел, хеш-таблица обеспечивает быстрый поиск в среднем.','https://en.wikipedia.org/wiki/Data_structure'],
['Программирование','Что такое рекурсивный спуск','парсер грамматика разбор синтаксис recursive descent','Рекурсивный спуск — метод синтаксического анализа, в котором функции соответствуют правилам грамматики и вызывают друг друга. Он понятен для небольших языков, но требует осторожности с левой рекурсией и неоднозначными правилами.','https://en.wikipedia.org/wiki/Recursive_descent_parser'],
['Программирование','Что такое объектно-ориентированное программирование','ооп объект класс инкапсуляция наследование полиморфизм','ООП организует программу вокруг объектов с состоянием и поведением. Часто выделяют инкапсуляцию, наследование и полиморфизм. Не всякую задачу нужно решать классами: функции и простые структуры могут быть проще.','https://en.wikipedia.org/wiki/Object-oriented_programming'],
['Программирование','Что такое REST API','rest api endpoint http get post put delete json','REST — архитектурный стиль построения веб-интерфейсов вокруг ресурсов и стандартных HTTP-семантик. Обычно API использует URL ресурсов, методы GET/POST/PUT/PATCH/DELETE и ответы JSON; важны авторизация, валидация и обработка ошибок.','https://developer.mozilla.org/en-US/docs/Glossary/REST'],
['Программирование','Что такое WebSocket','websocket соединение двунаправленный чат realtime','WebSocket поддерживает постоянное двунаправленное соединение между клиентом и сервером. Он удобен для чатов, игр и обновлений в реальном времени. Необходимо обрабатывать переподключение, авторизацию, лимиты и завершение соединения.','https://developer.mozilla.org/en-US/docs/Web/API/WebSockets_API'],
['Программирование','Что такое Service Worker','service worker offline pwa кэш приложение браузер','Service Worker — скрипт, который браузер запускает отдельно от страницы и который может управлять сетевыми запросами и кэшем. Его используют для офлайн-функций PWA; обновления требуют аккуратной стратегии, чтобы не смешивать версии файлов.','https://developer.mozilla.org/en-US/docs/Web/API/Service_Worker_API'],
['Программирование','Что такое PWA','pwa progressive web app установка офлайн сайт','Progressive Web App — веб-приложение, которое использует веб-технологии для приложения-подобного опыта. Возможности включают установку, адаптацию к экрану и иногда офлайн-режим; конкретная поддержка отличается по браузерам и ОС.','https://web.dev/explore/progressive-web-apps'],
['Программирование','Что такое адаптивный дизайн','responsive design мобильная версия css media queries','Адаптивный дизайн подстраивает интерфейс под размеры экрана, способ ввода и возможности устройства. Используй гибкие сетки, относительные размеры, media queries, подходящие размеры шрифта и проверку реальных мобильных сценариев.','https://web.dev/learn/design'],
['Программирование','Что такое доступность веба','accessibility a11y wcag клавиатура скринридер контраст','Доступность веба помогает людям с разными возможностями пользоваться сайтом. Практики включают семантический HTML, управление клавиатурой, заметный фокус, подписи полей, контраст и альтернативный текст для значимых изображений.','https://www.w3.org/WAI/fundamentals/accessibility-intro/'],
['Программирование','Что такое лицензия open source','open source лицензия mit apache gpl код использование','Open-source лицензия задаёт условия использования, изменения и распространения кода. Разные лицензии имеют разные требования к уведомлениям, распространению исходников и патентам. Перед публикацией проверь лицензию зависимостей и модели.','https://opensource.org/licenses'],
['Интернет','Что такое поисковая система','поисковик индексирование сканирование рейтинг выдача веб','Поисковая система обычно обнаруживает страницы, индексирует содержимое и ранжирует результаты по запросу. Выдача зависит от индекса, оценки релевантности, свежести и фильтров. API энциклопедии не является полным индексом всего веба.','https://www.google.com/search/howsearchworks/'],
['Интернет','Что такое браузер','браузер chrome firefox yandex веб страница html css javascript','Браузер загружает веб-ресурсы, разбирает HTML/CSS, исполняет JavaScript и предоставляет инструменты безопасности и разработчика. Один и тот же сайт может вести себя по-разному из-за движка, настроек приватности и поддержки API.','https://developer.mozilla.org/en-US/docs/Glossary/Browser'],
['Интернет','Что такое куки браузера','cookies cookie файлы браузер сессия приватность','Cookies — небольшие данные, которые сайт сохраняет в браузере и отправляет обратно в пределах заданных правил. Их используют для сессий и настроек. Флаги Secure, HttpOnly и SameSite помогают снизить часть рисков; не помещай в cookies лишние данные.','https://developer.mozilla.org/en-US/docs/Web/HTTP/Cookies'],
['Интернет','Что такое CDN','cdn сеть доставки контента кэш серверы скорость сайта','CDN распределяет кэшируемые ресурсы через сеть серверов ближе к посетителям. Это может уменьшить задержки и нагрузку на исходный сервер. Динамический и персональный контент требует отдельных правил кэширования.','https://www.cloudflare.com/learning/cdn/what-is-a-cdn/'],
['Интернет','Что такое кэш','cache кэш кеширование браузер данные скорость','Кэш хранит копию данных, чтобы сократить повторные запросы и ускорить работу. Ключевая задача — понять, когда копия устарела. HTTP предлагает Cache-Control, ETag и Last-Modified для управления повторным использованием ресурсов.','https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching'],
['Интернет','Что такое домен','доменное имя домен url адрес сайта доменная зона','Доменное имя — читаемый адрес в DNS, например example.com. Домен состоит из уровней и указывает на записи DNS. Само владение доменом не означает наличие хостинга, сертификата HTTPS или рабочего сайта.','https://www.icann.org/resources/pages/what-2012-02-25-en'],
['Интернет','Что такое URL','url адрес схема хост путь параметры ссылка','URL описывает расположение или способ обращения к ресурсу, обычно включает схему, хост, путь и необязательные параметры или фрагмент. Пользовательские URL нужно валидировать; опасно без проверки выполнять редиректы на произвольные адреса.','https://developer.mozilla.org/en-US/docs/Learn/Common_questions/Web_mechanics/What_is_a_URL'],
['Интернет','Что такое TLS-сертификат','tls ssl сертификат https удостоверяющий центр домен','TLS-сертификат связывает публичный ключ с именем сервера и проверяется по цепочке доверия. HTTPS защищает соединение, если TLS настроен корректно и имя хоста проходит проверку. Сертификат не доказывает добросовестность владельца сайта.','https://developer.mozilla.org/en-US/docs/Web/Security/Transport_Layer_Security'],
['Безопасность','Что такое менеджер паролей','password manager менеджер паролей хранилище генератор','Менеджер паролей хранит уникальные пароли в зашифрованном хранилище и может генерировать сильные случайные значения. Защищай мастер-пароль и восстанавливаемые копии, включай многофакторную аутентификацию и осторожно выбирай расширения браузера.','https://www.cisa.gov/secure-our-world/use-strong-passwords'],
['Безопасность','Что такое принцип наименьших привилегий','least privilege права доступа безопасность ограничение','Принцип наименьших привилегий означает выдавать пользователю или процессу только те права, которые необходимы для задачи. Это ограничивает последствия ошибок и компрометации. Права нужно периодически пересматривать и убирать неиспользуемые доступы.','https://csrc.nist.gov/glossary/term/least_privilege'],
['Безопасность','Что такое резервное копирование','backup бэкап резервная копия восстановление данные','Резервная копия — отдельная копия данных для восстановления после потери, повреждения или атаки. Проверяй восстановление на практике, храни копии отдельно от основной системы и используй правило нескольких копий на разных носителях.','https://www.cisa.gov/stopransomware/ransomware-guide'],
['Компьютеры','Что такое 64-битная система','64 bit x64 x86 архитектура адрес память совместимость','64-битная архитектура использует 64-битные регистры или адресные возможности в соответствующих частях системы. Она может поддерживать больше адресуемой памяти, но фактические лимиты зависят от ОС, процессора и конфигурации.','https://en.wikipedia.org/wiki/64-bit_computing'],
['Компьютеры','Что такое виртуальная память','виртуальная память pagefile swap память процесс операционная система','Виртуальная память даёт процессам собственное адресное пространство и помогает ОС управлять физической памятью. Страничный файл или swap могут перемещать данные на накопитель, но они обычно намного медленнее RAM.','https://en.wikipedia.org/wiki/Virtual_memory'],
['Компьютеры','Что такое терминал','терминал командная строка shell powershell bash команда','Терминал предоставляет текстовый интерфейс для оболочки, которая запускает команды и программы. PowerShell, Bash и cmd отличаются синтаксисом и доступными командами. Перед выполнением неизвестной команды нужно понимать, какие файлы или процессы она изменит.','https://learn.microsoft.com/en-us/powershell/'],
['Математика','Что такое дробь','дробь числитель знаменатель рациональное число','Дробь a/b означает отношение числителя a к ненулевому знаменателю b. Умножение дробей выполняется умножением числителей и знаменателей, а деление — умножением на обратную дробь. Сначала можно сокращать общие множители.','https://en.wikipedia.org/wiki/Fraction'],
['Математика','Площадь прямоугольника','площадь прямоугольника формула длина ширина геометрия','Площадь прямоугольника равна произведению длины на ширину: S = a × b. Если стороны измерены в метрах, площадь будет в квадратных метрах. Проверь, что обе стороны заданы в одинаковых единицах.','https://en.wikipedia.org/wiki/Rectangle'],
['Математика','Теорема Пифагора','пифагор гипотенуза катеты прямоугольный треугольник','В прямоугольном треугольнике квадрат гипотенузы равен сумме квадратов катетов: c² = a² + b². Например, при катетах 3 и 4 гипотенуза равна 5. Теорема применима к прямоугольным треугольникам в евклидовой геометрии.','https://en.wikipedia.org/wiki/Pythagorean_theorem'],
['Математика','Что такое логарифм','логарифм степень основание log математическая функция','Логарифм log_b(x) отвечает на вопрос, в какую степень нужно возвести основание b, чтобы получить x. Для вещественного логарифма обычно требуются b > 0, b ≠ 1 и x > 0. Например, log₂(8) = 3.','https://en.wikipedia.org/wiki/Logarithm'],
['Математика','Что такое уравнение','уравнение неизвестное переменная решение алгебра','Уравнение — равенство с неизвестными значениями. Решение — набор значений, при которых равенство верно. При преобразовании важно сохранять эквивалентность, особенно при делении на выражение, которое может быть нулём.','https://en.wikipedia.org/wiki/Equation'],
['Физика','Законы Ньютона','ньютон первый второй третий закон сила масса ускорение','Три закона Ньютона описывают движение в классической механике: инерцию, связь результирующей силы с ускорением (F = ma) и равные по модулю противоположные силы взаимодействия. Эти законы хорошо работают в подходящих нерелятивистских условиях.','https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion'],
['Физика','Что такое энергия','энергия работа движение тепло электричество сохранение','Энергия — физическая величина, характеризующая способность системы совершать работу или вызывать изменения. Существуют кинетическая, потенциальная, тепловая, химическая и другие формы; в изолированной системе энергия сохраняется.','https://en.wikipedia.org/wiki/Energy'],
['Физика','Что такое электрическая мощность','мощность ватт электричество напряжение ток формула p ui','Электрическая мощность в простом случае равна произведению напряжения на ток: P = U × I. Единица мощности — ватт. В цепях переменного тока расчёт активной мощности может дополнительно учитывать фазовый сдвиг и коэффициент мощности.','https://en.wikipedia.org/wiki/Electric_power'],
['Физика','Что такое температура','температура тепло энергия термометр цельсия кельвин','Температура характеризует тепловое состояние системы и связана со статистическим распределением энергии частиц. Цельсий и Кельвин отличаются сдвигом шкалы: 0 °C соответствует 273,15 K. Нельзя смешивать температуру и количество теплоты.','https://en.wikipedia.org/wiki/Temperature'],
['Биология','Что такое клетка','клетка биология органеллы мембрана организм','Клетка — базовая структурная и функциональная единица жизни. Она окружена мембраной и содержит систему молекул и структур, поддерживающих обмен веществ и воспроизведение. Бактерии обычно имеют одну прокариотическую клетку, животные — эукариотические клетки.','https://en.wikipedia.org/wiki/Cell_(biology)'],
['Биология','Что такое белок','белок протеин аминокислоты фермент структура организма','Белки — молекулы из цепочек аминокислот, которые сворачиваются в определённые структуры. Они участвуют в работе ферментов, транспорте, сигнализации, движении и поддержке тканей. Функция зависит от последовательности и трёхмерной формы.','https://en.wikipedia.org/wiki/Protein'],
['Биология','Что такое бактерии','бактерии микроорганизмы прокариоты микроб клетка','Бактерии — одноклеточные прокариотические организмы. Многие безвредны или полезны, некоторые вызывают болезни. Антибиотики действуют на определённые бактериальные процессы и не лечат вирусные инфекции; медицинское лечение требует оценки специалиста.','https://www.who.int/news-room/fact-sheets/detail/antimicrobial-resistance'],
['Биология','Чем вирус отличается от бактерии','вирус бактерия отличие инфекция клетка лечение','Бактерия — клеточный организм, а вирус состоит из генетического материала и белковой оболочки и размножается с использованием клеток хозяина. Антибиотики не действуют на вирусы. Диагностика и лечение зависят от конкретного возбудителя и симптомов.','https://www.cdc.gov/antibiotic-use/about/index.html'],
['Здоровье','Что такое сбалансированное питание','питание рацион овощи фрукты белок здоровье общие рекомендации','Сбалансированное питание включает разнообразные продукты, овощи и фрукты, источники белка, цельные злаки и подходящие человеку источники жиров. Индивидуальные потребности зависят от возраста, активности и состояния здоровья; универсального меню для всех нет.','https://www.who.int/news-room/fact-sheets/detail/healthy-diet'],
['Здоровье','Почему важна физическая активность','физическая активность упражнения здоровье мышцы сердце движение','Регулярная физическая активность поддерживает сердечно-сосудистое здоровье, силу, подвижность и психическое благополучие. Выбирай нагрузку по возможностям, увеличивай её постепенно и обсуждай ограничения со специалистом при медицинских проблемах.','https://www.who.int/news-room/fact-sheets/detail/physical-activity'],
['Здоровье','Что такое циркадный ритм','циркадный ритм биологические часы сон свет организм','Циркадные ритмы — внутренние циклы примерно суточной длительности, согласующие сон, бодрствование и другие процессы с окружением. Свет, регулярное расписание и смена часовых поясов влияют на синхронизацию биологических часов.','https://www.nigms.nih.gov/education/fact-sheets/Pages/circadian-rhythms.aspx'],
['Экономика','Что такое инфляция','инфляция рост цен покупательная способность экономика','Инфляция — устойчивое увеличение общего уровня цен, при котором на одну денежную единицу обычно можно купить меньше товаров и услуг. Её измеряют индексами цен; отдельные цены могут расти или падать иначе, чем общий показатель.','https://www.imf.org/en/Publications/fandd/issues/Series/Back-to-Basics/Inflation'],
['Экономика','Что такое сложный процент','сложный процент капитализация процент доход вложение','Сложный процент означает начисление процентов не только на первоначальную сумму, но и на уже накопленные проценты. При постоянной ставке и ежегодной капитализации формула: будущая сумма = начальная сумма × (1 + ставка)^число периодов. Реальная доходность зависит от налогов, комиссий и инфляции.','https://en.wikipedia.org/wiki/Compound_interest'],
['Экономика','Что такое бюджет','бюджет доходы расходы планирование деньги финансы','Личный бюджет сравнивает доходы и расходы за период. Полезно отслеживать обязательные траты, переменные расходы, сбережения и долги, а также оставлять резерв на непредвиденные ситуации. План нужно регулярно обновлять по фактическим данным.','https://www.consumerfinance.gov/consumer-tools/budgeting/'],
['География','Какова столица Франции','франция столица париж государство европа','Столица Франции — Париж. Это крупнейший политический, культурный и экономический центр страны. Для актуальных административных и туристических сведений следует проверять официальные источники.','https://en.wikipedia.org/wiki/Paris'],
['География','Какова столица Германии','германия столица берлин государство европа','Столица Германии — Берлин. Город является федеральной землёй и важным политическим, культурным и транспортным центром страны.','https://en.wikipedia.org/wiki/Berlin'],
['География','Какова столица Японии','япония столица токио государство азия','Столица и главный правительственный центр Японии — Токио. В нём расположены ключевые государственные учреждения и крупнейшая городская агломерация страны.','https://en.wikipedia.org/wiki/Tokyo'],
['География','Какова столица Италии','италия столица рим государство европа','Столица Италии — Рим. Город известен историческим наследием, античными памятниками и ролью политического центра современной Италии.','https://en.wikipedia.org/wiki/Rome'],
['География','Какова столица Испании','испания столица мадрид государство европа','Столица Испании — Мадрид. Здесь находятся центральные органы государственной власти и крупные культурные учреждения страны.','https://en.wikipedia.org/wiki/Madrid'],
['География','Какова столица Канады','канада столица оттава государство северная америка','Столица Канады — Оттава, расположенная в провинции Онтарио. Торонто — крупнейший город страны, но не её столица.','https://en.wikipedia.org/wiki/Ottawa'],
['Язык','Что такое синоним','синоним слова похожее значение русский язык словарь','Синонимы — слова с близким значением, например «смелый» и «храбрый». Они не всегда взаимозаменяемы во всех контекстах: оттенки значения, стиль и сочетаемость могут различаться.','https://en.wikipedia.org/wiki/Synonym'],
['Язык','Что такое антоним','антоним противоположное значение слова язык','Антонимы — слова с противоположными или контрастными значениями, например «высокий» и «низкий». Некоторые противопоставления абсолютны, другие образуют шкалу или зависят от контекста.','https://en.wikipedia.org/wiki/Antonym'],
['Язык','Что такое грамматика','грамматика язык правила слова предложение морфология синтаксис','Грамматика описывает правила строения языка. Обычно различают морфологию, изучающую формы слов, и синтаксис, изучающий сочетание слов в словосочетаниях и предложениях.','https://en.wikipedia.org/wiki/Grammar'],
['История','Что такое Древний Рим','древний рим республика империя история античность','Древний Рим прошёл путь от города-государства и республики до обширной империи. Римское право, инженерия, латинский язык и политические институты оказали длительное влияние на историю Европы и Средиземноморья.','https://en.wikipedia.org/wiki/Ancient_Rome'],
['История','Что такое Средневековье','средневековье эпоха история европа феодализм','Средневековьем обычно называют период европейской истории между античностью и ранним Новым временем, приблизительно с V по XV век. Границы условны, а история других регионов не укладывается в ту же схему.','https://en.wikipedia.org/wiki/Middle_Ages'],
['Наука','Что такое научный метод','научный метод гипотеза эксперимент доказательства проверка','Научный метод строит проверяемые гипотезы, сопоставляет предсказания с наблюдениями и обновляет объяснения при новых данных. Важны воспроизводимость, открытое описание методов, независимая проверка и готовность пересматривать выводы.','https://en.wikipedia.org/wiki/Scientific_method'],
['Наука','Что такое климатическое изменение','изменение климата глобальное потепление парниковый газ температура','Современное изменение климата включает долгосрочное потепление и изменения погодных закономерностей. Научные оценки указывают на доминирующую роль человеческих выбросов парниковых газов с промышленной эпохи; последствия и риски различаются по регионам.','https://climate.nasa.gov/'],
['Наука','Что такое возобновляемая энергия','возобновляемая энергия солнце ветер гидроэнергия электричество','Возобновляемая энергия поступает из источников, которые естественно восполняются, например солнечного света, ветра и водного потока. Её доступность зависит от погоды, места и хранения энергии; каждая технология имеет экологические и инфраструктурные ограничения.','https://www.iea.org/energy-system/renewables'],
['Космос','Что такое световой год','световой год расстояние свет космос астрономия парсек','Световой год — единица расстояния, а не времени. Он соответствует расстоянию, которое свет проходит в вакууме за один год, примерно 9,46 триллиона километров.','https://en.wikipedia.org/wiki/Light-year'],
['Космос','Что такое Марс','марс планета красная солнечная система атмосфера','Марс — четвёртая планета от Солнца, часто называемая Красной планетой из-за железистых минералов на поверхности. У него тонкая атмосфера, полярные шапки и следы древней водной активности; текущие условия на поверхности суровы для человека.','https://science.nasa.gov/mars/'],
['Продуктивность','Как составить план на день','план дня задачи приоритет список время концентрация','Выбери несколько главных результатов дня, оцени время, выдели самые важные задачи и оставь запас на неожиданности. Большой список дел без приоритетов часто мешает; лучше сделать меньше ключевых задач качественно.','https://en.wikipedia.org/wiki/Time_management'],
['Продуктивность','Что такое метод Помодоро','pomodoro помодоро фокус таймер перерывы работа','Метод Pomodoro делит работу на короткие сосредоточенные интервалы, часто около 25 минут, с небольшими перерывами. Интервалы можно адаптировать к задаче. Главное — заранее определить цель блока и убрать отвлечения.','https://en.wikipedia.org/wiki/Pomodoro_Technique'],
['Продуктивность','Как запоминать информацию','запоминание память повторение извлечение активное обучение','Для долговременного запоминания полезны активное воспроизведение, интервальные повторения, объяснение материала своими словами и применение на практике. Простое перечитывание создаёт ощущение знакомости, которое не всегда означает способность вспомнить информацию.','https://www.learningscientists.org/'],
['LEDERG','Почему LEDERG NEIRO иногда ошибается','ошибка ответ неточность классификатор база знаний ограничение','LEDERG NEIRO 0.2 сочетает MLP-классификатор, поиск по ограниченной курируемой базе и инструменты. Если запрос не совпадает с карточками или внешняя служба недоступна, система может не ответить как универсальная языковая модель. Уточняй вопрос и проверяй важные утверждения по источникам.','https://github.com/LEDERG777-TEXNARIC/LEDERG_NEIRO'],
['LEDERG','Как искать в интернете через LEDERG NEIRO','поиск интернете команда веб-поиск свежие данные источники','Напиши «поищи в интернете …» или «найди последние новости о …». Система попробует получить живую выдачу Wikipedia и покажет прямые ссылки на поисковики. Это не полный индекс всего веба и не гарантирует, что поисковые ссылки прочитаны автоматически.','https://www.mediawiki.org/wiki/API:Cross-site_requests'],
['LEDERG','Как работает время по Москве','время мск московское время Europe/Moscow дата часовой пояс','Часы в интерфейсе LEDERG NEIRO переводят часы устройства в зону Europe/Moscow. Для текущих дат Москва использует UTC+3. Если системные часы устройства неверны, локальное время тоже может быть неверным.','https://www.iana.org/time-zones']
);

const STOP = new Set(['что','как','это','для','или','при','в','во','на','по','и','а','но','к','из','с','со','о','об','от','до','не','ли','бы','мне','ты','вы','мы','он','она','они','про','есть','такое','такой','такая','можно','нужно','когда','где','какой','какая','какие','чем','помоги','расскажи','объясни','пожалуйста']);
function stemToken(word){if(!/[а-я]/u.test(word))return word;return word.replace(/(?:иями|ями|ами|ого|ему|ому|ыми|ими|ее|ие|ые|ое|ая|яя|ий|ый|ой|ую|юю|ых|их|ым|им|ом|ем|ах|ях|ов|ев|ей|ам|ям|ою|ею|ия|ья|а|я|ы|и|е|у|ю|ь)$/u,(suffix)=>word.length-suffix.length>=4?'':suffix)}
export function knowledgeTokens(text){return(String(text??'').toLocaleLowerCase('ru-RU').replace(/ё/g,'е').match(/[a-zа-я0-9+#.]+/giu)??[]).filter((word)=>word.length>1&&!STOP.has(word)).map(stemToken)}
export const KNOWLEDGE_BASE=records.map(([category,title,keywords,answer,url])=>({category,title,keywords,answer,source:{title,url}}));
export function searchKnowledgeMany(query,limit=3){const q=[...new Set(knowledgeTokens(query))];if(!q.length)return[];const matches=[];for(const item of KNOWLEDGE_BASE){const fields=(item.title+' '+item.keywords+' '+item.category).toLocaleLowerCase('ru-RU').replace(/ё/g,'е'),tokens=new Set(knowledgeTokens(fields)),hits=q.filter((word)=>tokens.has(word)),phraseBonus=item.keywords.toLocaleLowerCase('ru-RU').includes(String(query).toLocaleLowerCase('ru-RU').trim())?.25:0,coverage=hits.length/q.length,score=coverage*.8+Math.min(hits.length,4)*.04+phraseBonus;if(hits.length>=Math.min(2,q.length)&&score>=(q.length===1?.70:.38))matches.push({...item,score,matchedTerms:hits.length})}matches.sort((a,b)=>b.score-a.score||b.matchedTerms-a.matchedTerms);return matches.slice(0,Math.max(1,Math.min(5,limit)))}
export function searchKnowledge(query){return searchKnowledgeMany(query,1)[0]??null}